window.DOC_ID_TO_COVER_MAP = {
  "doc_nhan_tinh": "tuyet-mat-nhan-tinh",
  "doc_thuc_tinh": "thuc-tinh-nhan-thuc",
  "doc_cuong_gia": "tu-duy-cuong-gia",
  "doc_thuong_chien": "thuong-chien",
  "doc_huyen_co": "an-chua-huyen-co",
  "doc_sau_sac": "tu-duy-sau-sac",
  "doc_he_thong": "he-thong-manh-me",
  "doc_muu_luoc_tc": "muu-luoc-tai-chinh",
  "doc_luat_ngam_tc": "luat-ngam-tai-chinh",
  "doc_ban_chat_tc": "ban-chat-tai-chinh",
  "doc_muu_luoc_tt": "muu-luoc-tuoi-tre",
  "doc_tinh_cam": "tinh-cam-bi-tich",
  "doc_xuyen_thau": "xuyen-thau-nhan-tinh",
  "doc_logic_ngheo": "logic-nguoi-ngheo",
  "doc_den_trang": "nhan-tinh-den-trang"
};

/**
 * Render Book Cover HTML in different sizes
 * @param {string} docId - e.g. 'doc_cuong_gia'
 * @param {string} size - 'sm' (shop card), 'md' (backpack), 'lg' (reader banner)
 */
window.getBookCoverHTML = function(docId, size = 'sm') {
    const coverKey = window.DOC_ID_TO_COVER_MAP[docId] || docId;
    const cover = window.BOOK_COVERS_DATA[coverKey] || window.BOOK_COVERS_DATA['tuyet-mat-nhan-tinh'];
    if (!cover) return '<div class="book-cover-fallback">📜</div>';

    // Global gradient def reference: #gd
    if (size === 'sm') {
        return `
            <div class="hm-book-cover-mini" data-cover="${cover.id}" title="${cover.label}">
                <div class="hm-bcm-spine"></div>
                <div class="hm-bcm-glow"></div>
                <div class="hm-bcm-dial"></div>
                <div class="hm-bcm-emblem">
                    ${cover.svg}
                </div>
            </div>
        `;
    }

    if (size === 'md') {
        return `
            <div class="hm-book-cover-medium" data-cover="${cover.id}" title="${cover.label}">
                <div class="hm-bcm-spine"></div>
                <div class="hm-bcm-glow"></div>
                <div class="hm-bcm-border"></div>
                <div class="hm-bcm-kicker">${cover.kicker || 'TINH HOA'}</div>
                <div class="hm-bcm-dial-wrap">
                    <div class="hm-bcm-dial"></div>
                    <div class="hm-bcm-emblem">${cover.svg}</div>
                </div>
                <div class="hm-bcm-title">${cover.title}</div>
                <div class="hm-bcm-numeral">${cover.numeral || ''}</div>
            </div>
        `;
    }

    // Large Banner Size (for Document Reader Modal)
    return `
        <div class="hm-book-cover-large" data-cover="${cover.id}">
            <div class="hm-bcl-spine"></div>
            <div class="hm-bcl-glow"></div>
            <div class="hm-bcl-border"></div>
            <div class="hm-bcl-corner tl"></div>
            <div class="hm-bcl-corner br"></div>
            <div class="hm-bcl-inner">
                <div class="hm-bcl-kicker-wrap">
                    <div class="hm-bcl-line"></div>
                    <div class="hm-bcl-kicker">${cover.kicker || 'TINH HOA'}</div>
                    <div class="hm-bcl-line r"></div>
                </div>
                <div class="hm-bcl-center">
                    <div class="hm-bcl-dial-wrap">
                        <div class="hm-bcl-dial-rays"></div>
                        <div class="hm-bcl-dial-ring"></div>
                        <div class="hm-bcl-emblem">${cover.svg}</div>
                    </div>
                </div>
                <div class="hm-bcl-bottom">
                    <div class="hm-bcl-title">${cover.title}</div>
                    ${cover.subtitle ? `<div class="hm-bcl-subtitle">${cover.subtitle}</div>` : ''}
                    <div class="hm-bcl-footer-line">
                        <div class="hm-bcl-fline"></div>
                        <div class="hm-bcl-numeral">${cover.numeral || ''}</div>
                        <div class="hm-bcl-fline"></div>
                    </div>
                </div>
            </div>
        </div>
    `;
};
